#include "gmailactions.h"
#include <memory>
void GmailActions::apply(GoogleClient*c,const QString&id,const QString&action,GoogleClient::Done done){c->get("gmail/v1/users/me/threads/"+id,{{"format","minimal"}},[c,id,action,done](QJsonObject before,QString error){if(!error.isEmpty()){done({},error);return;}QString label=action=="archive"||action=="restore"?"INBOX":action=="star"?"STARRED":"UNREAD";bool add=action=="restore"||action=="unread";if(action=="star"){add=true;for(auto m:before["messages"].toArray())if(m.toObject()["labelIds"].toArray().contains("STARRED"))add=false;}QJsonObject record{{"thread",id},{"label",label},{"added",add},{"trash",action=="trash"},{"messages",before["messages"]}};auto finish=[done,record](QJsonObject result,QString e){if(e.isEmpty())result["undo"]=record;done(result,e);};if(action=="trash")c->mutate("POST","gmail/v1/users/me/threads/"+id+"/trash",{},finish);else c->mutate("POST","gmail/v1/users/me/threads/"+id+"/modify",QJsonObject{{add?"addLabelIds":"removeLabelIds",QJsonArray{label}}},finish);});}
void GmailActions::undo(GoogleClient*c,const QJsonObject&record,GoogleClient::Done done){auto messages=record["messages"].toArray();auto index=std::make_shared<int>(0);auto step=std::make_shared<std::function<void()>>();std::weak_ptr<std::function<void()>> weak=step;*step=[c,record,messages,index,done,weak]{auto keep=weak.lock();if(!keep)return;if(*index>=messages.size()){done({},{});return;}auto m=messages[(*index)++].toObject();QString id=m["id"].toString(),label=record["label"].toString();bool was=m["labelIds"].toArray().contains(label);auto apply=[c,id,label,was,keep,done]{c->mutate("POST","gmail/v1/users/me/messages/"+id+"/modify",QJsonObject{{was?"addLabelIds":"removeLabelIds",QJsonArray{label}}},[keep,done](QJsonObject result,QString e){if(e.isEmpty())(*keep)();else done(result,e);});};if(record["trash"].toBool()){if(m["labelIds"].toArray().contains("TRASH")){(*keep)();return;}bool inbox=m["labelIds"].toArray().contains("INBOX");c->mutate("POST","gmail/v1/users/me/messages/"+id+"/untrash",{},[c,id,inbox,keep,done](QJsonObject result,QString e){if(!e.isEmpty()){done(result,e);return;}c->mutate("POST","gmail/v1/users/me/messages/"+id+"/modify",QJsonObject{{inbox?"addLabelIds":"removeLabelIds",QJsonArray{"INBOX"}}},[keep,done](QJsonObject r,QString error){if(error.isEmpty())(*keep)();else done(r,error);});});}else apply();};(*step)();}
